const body = $json.body ?? {};

const operationId = body.operation_id;
const workItemId = body.work_item_id;
const revisionId = body.revision_id;

if (!operationId || !workItemId || !revisionId) {
  throw new Error('Content Factory envelope missing operation_id, work_item_id, or revision_id');
}

const executionId = `n8n-proof-${operationId}`;
const outputRevisionId = `n8n-output:${operationId}:${revisionId}`;

return [
  {
    json: {
      contract_version: 'n8n.execution.v0',
      operation_id: operationId,
      work_item_id: workItemId,
      revision_id: revisionId,
      execution: {
        runtime_execution_id: executionId,
        status: 'SUCCEEDED',
        started_at: new Date().toISOString(),
        completed_at: new Date().toISOString()
      },
      output: {
        output_revision_id: outputRevisionId,
        payload: {
          message: 'Content Factory external execution boundary reached through local n8n.',
          received_requested_outcome: body.requested_outcome ?? null,
          received_inputs: body.inputs ?? [],
          process_id: body.process_id ?? null,
          capability_id: body.capability_id ?? null
        },
        evidence_refs: [
          `n8n-execution:${executionId}`
        ]
      },
      provider_refs: [],
      tool_calls: [],
      agent_runs: []
    }
  }
];
